  "recovered_c": "uint64_t fn_03(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len == 0) {\n    return VERA_ERR;\n  }\n\n  uint64_t hash = 1;\n  uint64_t multiplier = 0;\n  uint64_t shift = 0;\n\n  for (size_t i = 0; i < len; i++) {\n    uint32_t temp = (uint32_t)multiplier;\n    uint32_t index = (uint32_t)i | 1;\n\n    if ((((index * index) & 7) == 1) && (DAT_00104008 == 0x3c71)) {\n      index = ((int)hash + (uint)*in) % 0xfff1;\n    } else {\n      index = (int)hash + 0x51e3U ^ shift;\n    }\n\n    hash = (uint64_t)index;\n\n    if ((((int)len + 1) * (int)len & 1U) != 0) || (DAT_00104010 != 0)) {\n      temp = (temp ^ (uint)(len << 7)) * 0x2d6b + DAT_00104008;\n      temp = temp ^ temp >> 0xb;\n    }\n\n    multiplier = (uint64_t)temp;\n    shift = shift + 0x1f9;\n    multiplier = (uint64_t)((temp + index) % 0xfff1);\n  }\n\n  if (DAT_00104010 != 0) {\n    shift = 0;\n    while (shift < DAT_00104010) {\n      hash = (uint64_t)((uint)(hash >> 5) ^ (int)hash * 8 ^ shift);\n      shift = shift + 1;\n    }\n  }\n\n  return hash | multiplier;\n}"
